{"policy":"permit (
    principal is User,
    action == Action::"approveDeployment",
    resource is Deployment
)
when {
    principal.isApprover || principal.isReleaseManager
};

forbid (
    principal is User,
    action == Action::"approveDeployment",
    resource is Deployment
)
when {
    (principal.isApprover || principal.isReleaseManager) &&
    resource.committer == principal
};

forbid (
    principal is User,
    action == Action::"approveDeployment",
    resource is Deployment
)
when {
    resource.changeRisk > context.extraScrutinyThreshold &&
    !resource.submittedForReview
};"}
